import 'package:flutter/material.dart';
class AuthTextField extends StatelessWidget { const AuthTextField({super.key, required this.label, required this.hintText, this.keyboardType, this.obscureText = false, this.suffixIcon}); final String label; final String hintText; final TextInputType? keyboardType; final bool obscureText; final Widget? suffixIcon; @override Widget build(BuildContext context) => Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(label, style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w300)), TextField(keyboardType: keyboardType, obscureText: obscureText, decoration: InputDecoration(hintText: hintText, suffixIcon: suffixIcon))]); }
